fn fmt_bigint(n: &BigInt, f: &mut fmt::Formatter) -> fmt::Result {
    const N_LEADING_DIGITS: u32 = 5;
    const N_TRAILING_DIGITS: u32 = 5;
    fn trailing_pow10() -> &'static BigInt {
        static TRAILING_POW10: OnceLock<BigInt> = OnceLock::new();
        TRAILING_POW10.get_or_init(|| BigInt::from(10u32.pow(N_TRAILING_DIGITS)))
    }

    let log = n.ilog10();
    let pow10 = BigInt::TEN.pow(log - N_LEADING_DIGITS);
    let leading: u32 = (n / pow10).as_();
    let pow10_lead: u32 = 10u32.pow(N_LEADING_DIGITS);
    let first_digit = leading / pow10_lead;
    let leading_digits = leading % pow10_lead;
    let trailing_digits = n % trailing_pow10();
    write!(f, "{first_digit}.{leading_digits:0>width$}...{trailing_digits:0>width$}e{log}", width=N_LEADING_DIGITS as usize)
}

