const N_LEFT_W: u128 = 2;
const N_LEFT_X: u128 = 2;
const N_LEFT_Z: u128 = 3;

const N_RIGHT_X: u128 = 1;
const N_RIGHT_V: u128 = 2;
const N_RIGHT_Y: u128 = 2;

pub fn bigint_print_max() -> &'static BigInt {
    static BIGINT_PRINT_MAX: OnceLock<BigInt> = OnceLock::new();
    BIGINT_PRINT_MAX.get_or_init(|| BigInt::from(u128::MAX))
}

impl BlockSimulator {
    pub fn new(do_left_strides: bool) -> Self {
        use BlockSymbol::*;
        Self {
            left_tape: vec![L],
            right_tape: vec![R1],
            state: HigherState::Right,
            base_steps: BigInt::FIVE,
            self_steps: 0,
            do_left_strides,
        }
    }

    pub fn new_with_tape(left_tape: Vec<BlockSymbol>, state: HigherState, right_tape: Vec<BlockSymbol>, do_left_strides: bool) -> Self {
        Self {
            left_tape, right_tape, state,
            base_steps: BigInt::ZERO,
            self_steps: 0,
            do_left_strides
        }
    }

    fn try_stride(&mut self) -> Option<BigInt> {
        use BlockSymbol::*;

        if self.state != HigherState::Left {
            return None;
        }

        let mut n_left: BigInt = BigInt::ONE;
        let mut n_left_by_block: Vec<BigInt> = Vec::new();
        for b in self.left_tape.iter().rev() {
            n_left_by_block.push(n_left);
            match *b {
                W => n_left = n_left.checked_mul(BigInt::TWO).unwrap(),
                Z => n_left = n_left / 2,
                X => n_left = n_left / 2 + n_left % 2,
                _ => return None,
            }
            if n_left == BigInt::ZERO {
                break;
            }
        }

        let mut n_basic_steps = BigInt::ZERO;
        for (b, b_n_left) in self.left_tape.iter_mut().rev().zip(n_left_by_block) {
            match b {
                W => n_basic_steps += BigInt::from(N_LEFT_W + N_RIGHT_X + N_RIGHT_V) * b_n_left,
                X => {
                    n_basic_steps += BigInt::from(N_LEFT_X + N_RIGHT_Y + N_LEFT_Z) * (b_n_left / 2);
                    if b_n_left % 2 == 1 {
                        n_basic_steps += BigInt::from(N_LEFT_X + N_RIGHT_Y);
                        *b = Z;
                    }
                }
                Z => {
                    n_basic_steps += BigInt::from(N_LEFT_X + N_RIGHT_Y + N_LEFT_Z) * (b_n_left / 2);
                    if b_n_left % 2 == 1 {
                        n_basic_steps += BigInt::from(N_LEFT_Z);
                        *b = X;
                    }
                }
                _ => unreachable!()
            }
        }
        self.state = HigherState::Right;
        Some(n_basic_steps)
    }

    pub fn step(&mut self) -> Result<(), SimError> {
        if self.do_left_strides {
            if let Some(new_base_steps) = self.try_stride() {
                self.base_steps = self.base_steps.checked_add(new_base_steps).unwrap();
                self.self_steps += 1;
                return Ok(())
            }
        }

        let new_base_steps = self.basic_step()?;
        self.base_steps = self.base_steps.checked_add(new_base_steps.into()).unwrap();
        self.self_steps += 1;
        Ok(())
    }

    pub fn run_length_encode_state(&self) -> RLESimState {
        RLESimState {
            left_tape:  run_length_encode(&self.left_tape), 
            right_tape: run_length_encode(&self.right_tape), 
            state: self.state,
            base_steps: self.base_steps,
            self_steps: self.self_steps
        }
    }
}

struct BlockRun(BlockSymbol, usize);

fn run_length_encode(v: &Vec<BlockSymbol>) -> Vec<BlockRun> {
    v[..].chunk_by(|a, b| a == b)
        .map(|sl| BlockRun(sl.first().unwrap().clone(), sl.len()))
        .collect()
}

impl fmt::Display for BlockRun {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}", self.0)?;

        if self.1 > 1 {
            write!(f, "^{}", self.1)?;
        }
        Ok(())
    }
}
